#include "dse/storage/posting_codec.hpp"
#include <gtest/gtest.h>
#include <array>
TEST(VariableByteCodec, RoundTripsBoundariesAndSortedDeltas){for(const std::uint32_t value:{0U,1U,127U,128U,16383U,16384U,0xffffffffU}){std::vector<std::byte> encoded;dse::storage::VariableByteCodec::encode(value,encoded);std::size_t offset{};auto decoded=dse::storage::VariableByteCodec::decode(encoded,offset);ASSERT_TRUE(decoded);EXPECT_EQ(*decoded,value);EXPECT_EQ(offset,encoded.size());}constexpr std::array values{1U,2U,130U,1'000'000U};auto encoded=dse::storage::VariableByteCodec::encode_deltas(values);ASSERT_TRUE(encoded);auto decoded=dse::storage::VariableByteCodec::decode_deltas(*encoded,values.size(),values.size());ASSERT_TRUE(decoded);EXPECT_EQ(*decoded,std::vector<std::uint32_t>(values.begin(),values.end()));}
TEST(VariableByteCodec, RejectsMalformedAndBoundedStreams){std::size_t offset{};const std::array truncated{std::byte{0x01}};EXPECT_EQ(dse::storage::VariableByteCodec::decode(truncated,offset).error().code,dse::storage::CodecErrorCode::truncated);offset=0;const std::array overflow{std::byte{0x7f},std::byte{0x7f},std::byte{0x7f},std::byte{0x7f},std::byte{0x90}};EXPECT_EQ(dse::storage::VariableByteCodec::decode(overflow,offset).error().code,dse::storage::CodecErrorCode::overflow);const std::array zero_delta{std::byte{0x80}};EXPECT_EQ(dse::storage::VariableByteCodec::decode_deltas(zero_delta,1,1).error().code,dse::storage::CodecErrorCode::invalid_order);EXPECT_EQ(dse::storage::VariableByteCodec::decode_deltas({},2,1).error().code,dse::storage::CodecErrorCode::resource_limit);}
